-- What each column means and how sure we are of it. CS2's GSI feed only describes the local
-- player (or whoever they spectate), so several values are inferred or estimated. Tags:
-- OBSERVED = read straight from GSI, DERIVED = computed from observed values,
-- INFERRED = a best guess from changes between payloads, ESTIMATED = a heuristic,
-- PARTIAL = only what the recorder happened to see.

COMMENT ON TABLE "players" IS 'Everyone known by Steam ID: recorders, plus players seen as partial sightings.';--> statement-breakpoint
COMMENT ON COLUMN "players"."name" IS 'OBSERVED: the most recent name seen in GSI for this Steam ID.';--> statement-breakpoint
COMMENT ON COLUMN "players"."last_recorded_at" IS 'When this player last saved a match of their own (null if never a recorder).';--> statement-breakpoint

COMMENT ON TABLE "matches" IS 'One recording of a match by one player (the recorder). Several friends recording the same game give several rows sharing game_id.';--> statement-breakpoint
COMMENT ON COLUMN "matches"."id" IS 'Generated by the recording client, so re-uploads are idempotent.';--> statement-breakpoint
COMMENT ON COLUMN "matches"."game_id" IS 'INFERRED: recordings believed to be the same game (same map and mode, start within 10 min, matching score). Equals id when no other recording matched.';--> statement-breakpoint
COMMENT ON COLUMN "matches"."started_at" IS 'OBSERVED: when the recorder first saw the match live (not the server start time).';--> statement-breakpoint
COMMENT ON COLUMN "matches"."ended_at" IS 'OBSERVED: gameover payload time, or the last in-match payload for incomplete matches.';--> statement-breakpoint
COMMENT ON COLUMN "matches"."duration_s" IS 'DERIVED: ended_at - started_at, as seen by the recorder.';--> statement-breakpoint
COMMENT ON COLUMN "matches"."status" IS 'complete = gameover seen; incomplete = recorder left, crashed or timed out first.';--> statement-breakpoint
COMMENT ON COLUMN "matches"."result" IS 'DERIVED from the final team scores; incomplete when the match was not seen to finish.';--> statement-breakpoint
COMMENT ON COLUMN "matches"."joined_mid_match" IS 'INFERRED: the first round seen was not round 1.';--> statement-breakpoint
COMMENT ON COLUMN "matches"."first_round" IS 'OBSERVED: first round number the recorder saw.';--> statement-breakpoint
COMMENT ON COLUMN "matches"."my_team_start" IS 'OBSERVED: the recorder''s side (CT/T) in the first round seen.';--> statement-breakpoint
COMMENT ON COLUMN "matches"."score_mine" IS 'OBSERVED: the recorder''s team score at the end (follows the team across the halftime side swap).';--> statement-breakpoint
COMMENT ON COLUMN "matches"."kills" IS 'OBSERVED: player.match_stats.kills at the end.';--> statement-breakpoint
COMMENT ON COLUMN "matches"."hs_kills" IS 'DERIVED: sum of round_killhs at each round end. Rounds the recorder did not see are missing.';--> statement-breakpoint
COMMENT ON COLUMN "matches"."damage" IS 'DERIVED: sum of round_totaldmg at each round end. Can miss damage dealt after death (e.g. a molotov still burning) and rounds not seen.';--> statement-breakpoint
COMMENT ON COLUMN "matches"."rounds_played" IS 'DERIVED: rounds the recorder saw finish.';--> statement-breakpoint
COMMENT ON COLUMN "matches"."adr" IS 'DERIVED: damage / rounds_played. Approximate, see damage.';--> statement-breakpoint
COMMENT ON COLUMN "matches"."hs_pct" IS 'DERIVED: 100 * hs_kills / kills counted in seen rounds.';--> statement-breakpoint
COMMENT ON COLUMN "matches"."kd" IS 'DERIVED: kills / deaths (kills when deaths = 0).';--> statement-breakpoint
COMMENT ON COLUMN "matches"."round_wins" IS 'OBSERVED: map.round_wins from GSI, round number -> reason (e.g. ct_win_elimination).';--> statement-breakpoint
COMMENT ON COLUMN "matches"."source" IS 'direct = written by a local copy with DATABASE_URL; upload = sent through /api/upload.';--> statement-breakpoint

COMMENT ON TABLE "rounds" IS 'The recorder''s rounds. partial = the round was not seen from its start.';--> statement-breakpoint
COMMENT ON COLUMN "rounds"."winner_side" IS 'OBSERVED: from round.win_team or map.round_wins.';--> statement-breakpoint
COMMENT ON COLUMN "rounds"."i_won" IS 'DERIVED: winner_side = my_side.';--> statement-breakpoint
COMMENT ON COLUMN "rounds"."kills" IS 'OBSERVED: player.state.round_kills at the last own payload of the round.';--> statement-breakpoint
COMMENT ON COLUMN "rounds"."damage" IS 'OBSERVED: player.state.round_totaldmg at the last own payload of the round; may miss damage after death.';--> statement-breakpoint
COMMENT ON COLUMN "rounds"."assists" IS 'INFERRED: change in match_stats.assists across the round.';--> statement-breakpoint
COMMENT ON COLUMN "rounds"."survived" IS 'INFERRED: no death in match_stats and never seen dead or spectating. Null when unknown.';--> statement-breakpoint
COMMENT ON COLUMN "rounds"."health_end" IS 'OBSERVED: last health seen for the recorder in this round.';--> statement-breakpoint
COMMENT ON COLUMN "rounds"."money_freeze_start" IS 'OBSERVED: money at the first freeze-time payload.';--> statement-breakpoint
COMMENT ON COLUMN "rounds"."money_freeze_end" IS 'OBSERVED: money when buying ended (freeze end, or within 15 s of going live).';--> statement-breakpoint
COMMENT ON COLUMN "rounds"."equip_value" IS 'OBSERVED: player.state.equip_value when buying ended.';--> statement-breakpoint
COMMENT ON COLUMN "rounds"."weapons_freeze_end" IS 'OBSERVED: weapons held when buying ended.';--> statement-breakpoint
COMMENT ON COLUMN "rounds"."buy_type" IS 'ESTIMATED: pistol/eco/force/full/save from equip_value and money (see src/lib/cs2/economy.ts).';--> statement-breakpoint
COMMENT ON COLUMN "rounds"."mvp" IS 'INFERRED: match_stats.mvps went up during the round.';--> statement-breakpoint
COMMENT ON COLUMN "rounds"."started_at" IS 'OBSERVED: when freeze time was first seen (receive time, not server time).';--> statement-breakpoint
COMMENT ON COLUMN "rounds"."duration_s" IS 'DERIVED: ended_at - live_at, from receive times.';--> statement-breakpoint
COMMENT ON COLUMN "rounds"."partial" IS 'The round''s freeze time was not seen (joined or reconnected mid-round), so some values are missing.';--> statement-breakpoint

COMMENT ON TABLE "kill_events" IS 'INFERRED: one row per increase in round_kills. GSI has no kill feed.';--> statement-breakpoint
COMMENT ON COLUMN "kill_events"."at" IS 'INFERRED: when the increase was seen, not the exact kill time.';--> statement-breakpoint
COMMENT ON COLUMN "kill_events"."weapon" IS 'INFERRED: the recorder''s active weapon at that moment (can be wrong for grenades and quick switches).';--> statement-breakpoint
COMMENT ON COLUMN "kill_events"."headshot" IS 'INFERRED: round_killhs went up together with round_kills.';--> statement-breakpoint

COMMENT ON TABLE "sightings" IS 'PARTIAL: other players the recorder spectated (usually teammates while dead). Stats are as last seen, not final.';--> statement-breakpoint
COMMENT ON COLUMN "sightings"."teammate" IS 'INFERRED: side matched the recorder''s side when seen.';--> statement-breakpoint
COMMENT ON COLUMN "sightings"."kills" IS 'PARTIAL: match_stats.kills when last spectated, not at match end.';--> statement-breakpoint
COMMENT ON COLUMN "sightings"."first_round" IS 'First round in which the recorder spectated this player.';--> statement-breakpoint
COMMENT ON COLUMN "sightings"."last_round" IS 'Last round in which the recorder spectated this player.';--> statement-breakpoint

COMMENT ON TABLE "raw_payloads" IS 'Optional raw GSI payloads (STORE_RAW_PAYLOADS=1, direct mode only). Prune with yarn db:cleanup.';--> statement-breakpoint
COMMENT ON TABLE "steam_links" IS 'A site account''s claimed Steam ID (first claim wins; ownership is not verified) and upload key.';--> statement-breakpoint
COMMENT ON COLUMN "steam_links"."upload_key_hash" IS 'SHA-256 of the upload key. The key itself is shown once and never stored.';
